INSERT INTO company_members VALUES('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111');
INSERT INTO master_lenders(id,user_id,company_id,name,funding_source_notes,criteria_confidence) VALUES('22222222-2222-4222-8222-222222222222','11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','Local Lender','original','imported');
INSERT INTO master_lenders(id,user_id,company_id,name) VALUES('33333333-3333-4333-8333-333333333333','99999999-9999-4999-8999-999999999999','bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb','Other tenant');
SELECT set_config('request.user_id','11111111-1111-4111-8111-111111111111',false);
SET ROLE authenticated;
DO $$ DECLARE r jsonb; n int; ts timestamptz; BEGIN
 r:=mcp_update_lender('22222222-2222-4222-8222-222222222222','{"funding_source_notes":"next"}','append',NULL,true);
 IF r->'diff'->0->>'new' <> E'original\n\nnext' THEN RAISE EXCEPTION 'dry-run append failed'; END IF;
 IF (SELECT funding_source_notes FROM master_lenders WHERE name='Local Lender')<>'original' THEN RAISE EXCEPTION 'dry-run wrote data'; END IF;
 r:=mcp_update_lender('22222222-2222-4222-8222-222222222222','{"funding_source_notes":"next"}','append',NULL,false,'local test','reason');
 IF r->'lender'->>'funding_source_notes'<>E'original\n\nnext' THEN RAISE EXCEPTION 'append failed'; END IF;
 IF NOT EXISTS(SELECT 1 FROM lender_audit_logs WHERE field_changed='funding_source_notes' AND source='local test' AND change_reason='reason') THEN RAISE EXCEPTION 'audit provenance missing'; END IF;
 r:=mcp_update_lender('22222222-2222-4222-8222-222222222222','{"funding_source_notes":"first"}','prepend');
 IF r->'lender'->>'funding_source_notes'<>E'first\n\noriginal\n\nnext' THEN RAISE EXCEPTION 'prepend failed'; END IF;
 r:=mcp_update_lender('22222222-2222-4222-8222-222222222222','{"notes":"bad"}');
 RAISE EXCEPTION 'unknown accepted';
 EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%unknown master_lenders field%' THEN RAISE; END IF;
END $$;
DO $$ DECLARE r jsonb; nid uuid; cid uuid; BEGIN
 BEGIN PERFORM mcp_update_lender('33333333-3333-4333-8333-333333333333','{"name":"stolen"}'); RAISE EXCEPTION 'cross-tenant accepted'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM mcp_update_lender('22222222-2222-4222-8222-222222222222','{"user_id":"99999999-9999-4999-8999-999999999999"}'); RAISE EXCEPTION 'identity accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%Immutable%' THEN RAISE; END IF; END;
 BEGIN PERFORM mcp_update_lender('22222222-2222-4222-8222-222222222222',jsonb_build_object('funding_source_notes',repeat('x',20000)),'append'); RAISE EXCEPTION 'length accepted'; EXCEPTION WHEN OTHERS THEN IF SQLERRM NOT LIKE '%exceeds 20000%' THEN RAISE; END IF; END;
 r:=mcp_update_lender('22222222-2222-4222-8222-222222222222','{"name":"wrong"}','replace','2000-01-01');
 IF r->>'error'<>'concurrency_conflict' OR r->'lender'->>'name'<>'Local Lender' THEN RAISE EXCEPTION 'conflict failed'; END IF;
 r:=mcp_write_lender_related('lender_notes','create','22222222-2222-4222-8222-222222222222',NULL,'{"body":"old","tags":["tag"],"is_flag":true}'); nid:=(r->'record'->>'id')::uuid;
 r:=mcp_write_lender_related('lender_notes','update','22222222-2222-4222-8222-222222222222',nid,'{"body":"new"}');
 IF NOT EXISTS(SELECT 1 FROM lender_master_note_history WHERE note_id=nid AND old_record->>'body'='old') THEN RAISE EXCEPTION 'note history failed'; END IF;
 r:=mcp_write_lender_related('lender_notes','delete','22222222-2222-4222-8222-222222222222',nid,'{}',true);
 IF EXISTS(SELECT 1 FROM lender_notes WHERE id=nid) THEN RAISE EXCEPTION 'delete failed'; END IF;
 r:=mcp_write_lender_related('lender_contacts','create','22222222-2222-4222-8222-222222222222',NULL,'{"name":"Person","is_primary":true}'); cid:=(r->'record'->>'id')::uuid;
 r:=mcp_write_lender_related('lender_contacts','create','22222222-2222-4222-8222-222222222222',NULL,'{"name":"Person 2","is_primary":true}');
 IF (SELECT count(*) FROM lender_contacts WHERE is_primary)<>1 THEN RAISE EXCEPTION 'primary count failed'; END IF;
 r:=mcp_write_lender_related('lender_contacts','update','22222222-2222-4222-8222-222222222222',cid,'{"contact_id":null}');
 IF r->'record'->'contact_id'<>'null' THEN RAISE EXCEPTION 'unlink failed'; END IF;
 r:=mcp_write_lender_related('lender_attachments','create','22222222-2222-4222-8222-222222222222',NULL,'{"name":"test.pdf","file_path":"11111111-1111-4111-8111-111111111111/Local Lender/test.pdf","size_bytes":10,"category":"general","content_type":"application/pdf"}');
 r:=mcp_write_lender_related('lender_attachments','update','22222222-2222-4222-8222-222222222222',(r->'record'->>'id')::uuid,'{"name":"renamed.pdf"}');
 IF r->'record'->>'name'<>'renamed.pdf' THEN RAISE EXCEPTION 'attachment rename failed'; END IF;
 r:=mcp_archive_lender('22222222-2222-4222-8222-222222222222',true,false);
 IF r->'lender'->>'active'<>'false' THEN RAISE EXCEPTION 'archive failed'; END IF;
END $$;
SELECT 'Isolated SQL assertions passed';
